// Content with portions generated by generative AI platform
package org.eclipse.kura.core.configuration;

import static org.eclipse.kura.core.configuration.ExternalMetatypeBundle.INT_ATTR;
import static org.eclipse.kura.core.configuration.ExternalMetatypeBundle.OPTIONAL_ATTR;
import static org.eclipse.kura.core.configuration.ExternalMetatypeBundle.OPTION_ATTR;
import static org.eclipse.kura.core.configuration.ExternalMetatypeBundle.REQUIRED_PID;
import static org.eclipse.kura.core.configuration.ExternalMetatypeBundle.VALIDATED_PID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.eclipse.kura.KuraPartialSuccessException;
import org.eclipse.kura.configuration.ComponentConfiguration;
import org.eclipse.kura.configuration.ConfigurationService;
import org.eclipse.kura.core.configuration.testcomponent.ExternalComponent;
import org.junit.Test;
import org.osgi.framework.BundleContext;
import org.osgi.framework.FrameworkUtil;
import org.osgi.util.tracker.ServiceTracker;

public class ExternalBundleValidationTest {

    private static final long TIMEOUT_MS = 30000;
    private static final long POLL_INTERVAL_MS = 100;

    private final BundleContext bundleContext = FrameworkUtil.getBundle(ExternalBundleValidationTest.class)
            .getBundleContext();

    private ConfigurationService configurationService;
    private Exception occurredException;

    @Test
    public void valueAtTheLowerBoundIsApplied() throws Exception {
        givenExternalBundleComponents();
        givenIntegerValue(5);

        whenValueIsUpdated(VALIDATED_PID, INT_ATTR, 1);

        thenNoExceptionOccurred();
        thenComponentReceives(VALIDATED_PID, INT_ATTR, 1);
        thenLatestSnapshotHolds(VALIDATED_PID, INT_ATTR, 1);
    }

    @Test
    public void valueAtTheUpperBoundIsApplied() throws Exception {
        givenExternalBundleComponents();
        givenIntegerValue(5);

        whenValueIsUpdated(VALIDATED_PID, INT_ATTR, 10);

        thenNoExceptionOccurred();
        thenComponentReceives(VALIDATED_PID, INT_ATTR, 10);
        thenLatestSnapshotHolds(VALIDATED_PID, INT_ATTR, 10);
    }

    @Test
    public void valueBelowTheLowerBoundIsRejected() throws Exception {
        givenExternalBundleComponents();
        givenIntegerValue(5);

        whenValueIsUpdated(VALIDATED_PID, INT_ATTR, 0);

        thenUpdateIsRejectedWith(KuraErrorCode.CONFIGURATION_ATTRIBUTE_INVALID);
        thenConfigurationHolds(VALIDATED_PID, INT_ATTR, 5);
        thenLatestSnapshotHolds(VALIDATED_PID, INT_ATTR, 5);
    }

    @Test
    public void valueAboveTheUpperBoundIsRejected() throws Exception {
        givenExternalBundleComponents();
        givenIntegerValue(5);

        whenValueIsUpdated(VALIDATED_PID, INT_ATTR, 11);

        thenUpdateIsRejectedWith(KuraErrorCode.CONFIGURATION_ATTRIBUTE_INVALID);
        thenConfigurationHolds(VALIDATED_PID, INT_ATTR, 5);
        thenLatestSnapshotHolds(VALIDATED_PID, INT_ATTR, 5);
    }

    @Test
    public void valueOfTheWrongTypeIsRejected() throws Exception {
        givenExternalBundleComponents();
        givenIntegerValue(5);

        whenValueIsUpdated(VALIDATED_PID, INT_ATTR, "eleven");

        thenUpdateIsRejectedWith(KuraErrorCode.CONFIGURATION_ATTRIBUTE_INVALID);
        thenConfigurationHolds(VALIDATED_PID, INT_ATTR, 5);
        thenLatestSnapshotHolds(VALIDATED_PID, INT_ATTR, 5);
    }

    @Test
    public void valueOutsideTheOptionsIsRejected() throws Exception {
        givenExternalBundleComponents();
        givenIntegerValue(5);

        whenValueIsUpdated(VALIDATED_PID, OPTION_ATTR, "third");

        thenUpdateIsRejectedWith(KuraErrorCode.CONFIGURATION_ATTRIBUTE_INVALID);
        thenConfigurationDoesNotHold(VALIDATED_PID, OPTION_ATTR, "third");
        thenLatestSnapshotDoesNotHold(VALIDATED_PID, OPTION_ATTR, "third");
    }

    @Test
    public void missingRequiredAttributeIsRejected() throws Exception {
        givenExternalBundleComponents();

        whenValueIsUpdated(REQUIRED_PID, OPTIONAL_ATTR, "y");

        thenUpdateIsRejectedWith(KuraErrorCode.CONFIGURATION_REQUIRED_ATTRIBUTE_MISSING);
        thenConfigurationDoesNotHold(REQUIRED_PID, OPTIONAL_ATTR, "y");
    }

    private void givenExternalBundleComponents() throws Exception {
        ExternalMetatypeBundle.install(this.bundleContext);
        this.configurationService = waitForService(ConfigurationService.class);

        assertNotNull(this.configurationService);

        await(() -> isTracked(VALIDATED_PID) && isTracked(REQUIRED_PID));

        assertTrue(isTracked(VALIDATED_PID));
        assertTrue(isTracked(REQUIRED_PID));
    }

    private void givenIntegerValue(final int value) throws KuraException {
        this.configurationService.updateConfiguration(VALIDATED_PID, Collections.singletonMap(INT_ATTR, value), true);

        thenComponentReceives(VALIDATED_PID, INT_ATTR, value);
    }

    private void whenValueIsUpdated(final String pid, final String attribute, final Object value) {
        try {
            this.configurationService.updateConfiguration(pid, Collections.singletonMap(attribute, value), true);
        } catch (final Exception e) {
            this.occurredException = e;
        }
    }

    private void thenNoExceptionOccurred() {
        assertNull(this.occurredException);
    }

    private void thenUpdateIsRejectedWith(final KuraErrorCode code) {
        assertTrue("expected a KuraPartialSuccessException but got " + this.occurredException,
                this.occurredException instanceof KuraPartialSuccessException);

        final List<Throwable> causes = ((KuraPartialSuccessException) this.occurredException).getCauses();

        assertEquals(1, causes.size());
        assertTrue(causes.get(0) instanceof KuraException);
        assertEquals(code, ((KuraException) causes.get(0)).getCode());
    }

    private void thenComponentReceives(final String pid, final String attribute, final Object value) {
        await(() -> value.equals(receivedValue(pid, attribute)));

        assertEquals(value, receivedValue(pid, attribute));
    }

    private void thenConfigurationHolds(final String pid, final String attribute, final Object value)
            throws KuraException {
        assertEquals(value, currentValue(pid, attribute));
        assertEquals(value, receivedValue(pid, attribute));
    }

    private void thenConfigurationDoesNotHold(final String pid, final String attribute, final Object value)
            throws KuraException {
        assertNotEquals(value, currentValue(pid, attribute));
        assertNotEquals(value, receivedValue(pid, attribute));
    }

    private void thenLatestSnapshotHolds(final String pid, final String attribute, final Object value)
            throws KuraException {
        assertEquals(value, latestSnapshotValue(pid, attribute));
    }

    private void thenLatestSnapshotDoesNotHold(final String pid, final String attribute, final Object value)
            throws KuraException {
        assertNotEquals(value, latestSnapshotValue(pid, attribute));
    }

    private Object currentValue(final String pid, final String attribute) throws KuraException {
        final ComponentConfiguration configuration = this.configurationService.getComponentConfiguration(pid);

        assertNotNull(configuration);
        return configuration.getConfigurationProperties().get(attribute);
    }

    private Object latestSnapshotValue(final String pid, final String attribute) throws KuraException {
        final long latestId = Collections.max(this.configurationService.getSnapshots());

        for (final ComponentConfiguration configuration : this.configurationService.getSnapshot(latestId)) {
            if (pid.equals(configuration.getPid())) {
                return configuration.getConfigurationProperties().get(attribute);
            }
        }

        fail("snapshot " + latestId + " does not contain " + pid);
        return null;
    }

    private static Object receivedValue(final String pid, final String attribute) {
        final Map<String, Object> properties = ExternalComponent.getProperties(pid);

        return properties == null ? null : properties.get(attribute);
    }

    private boolean isTracked(final String pid) {
        return this.configurationService.getConfigurableComponentPids().contains(pid);
    }

    private <T> T waitForService(final Class<T> service) throws InterruptedException {
        final ServiceTracker<T, T> tracker = new ServiceTracker<>(this.bundleContext, service, null);
        tracker.open();

        try {
            return tracker.waitForService(TIMEOUT_MS);
        } finally {
            tracker.close();
        }
    }

    private static void await(final BooleanSupplier condition) {
        final long deadline = System.currentTimeMillis() + TIMEOUT_MS;

        while (!condition.getAsBoolean() && System.currentTimeMillis() < deadline) {
            try {
                Thread.sleep(POLL_INTERVAL_MS);
            } catch (final InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }
        }
    }
}
